Translate the original parabola right $1$ unit and down $2$ units. Its shape is unchanged, and the vertex moves from $(0,0)$ to $(1,-2)$.

[tikz]
\begin{tikzpicture}[x=8mm,y=5mm,every node/.style={text=black,font=\fontsize{10}{12}\selectfont}]
\definecolor{curveblue}{HTML}{268CFF}
\draw[black,<->] (-2.6,0)--(3.6,0);
\draw[black,<->] (0,-3)--(0,5);
\path (3.6,0) node[right] {$x$} (0,5) node[above] {$y$};
\foreach \x in {-2,-1,1,2,3}{\draw[black] (\x,-0.08)--(\x,0.08);\path (\x,0) node[below,font=\fontsize{8.5}{10}\selectfont] {$\x$};}
\foreach \y in {-2,2,4}{\draw[black] (-0.05,\y)--(0.05,\y);\path (0,\y) node[left,font=\fontsize{8.5}{10}\selectfont] {$\y$};}
\draw[black,dashed,thick,<->,domain=-2.15:2.15,samples=100] plot (\x,{(\x)*(\x)});
\draw[curveblue,thick,<->,domain=-1.5:3.5,samples=100] plot (\x,{(\x-1)*(\x-1)-2});
\fill[curveblue] (1,-2) circle (1.5pt);
\path (1,-2) node[below right] {$(1,-2)$};
\end{tikzpicture}
[/tikz]

